// JAH demo program — Shor order-finding demo (N=15, a=7)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function modpow(a,e,n){ var r=1; a%=n; while(e>0){ if(e&1)r=(r*a)%n; a=(a*a)%n; e>>=1; } return r; }
function order(a,n){ var r=1; while(modpow(a,r,n)!==1&&r<100)r++; return r; }
function gcd(a,b){ return b?gcd(b,a%b):a; }
var N=15,a=7,r=order(a,N);
var f1=gcd(modpow(a,r/2,N)-1+N,N), f2=gcd(modpow(a,r/2,N)+1,N);
check("order of 7 mod 15", r, 4);
check("factor 1", f1, 3);
check("factor 2", f2, 5);
check("factors multiply to N", f1*f2, 15);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

