function sift(n, seed){ var a=seed; function r(){ a=(Math.imul(a,1103515245)+12345)&0x7fffffff; return a/0x7fffffff; }
  var kept=0; for(var i=0;i<n;i++){ if(r()<0.5===r()<0.5)kept++; } return kept; }
