// JAH demo program — Randomness quality check (seeded demo)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function bits(n,seed){ var a=seed,out=[]; for(var i=0;i<n;i++){ a=(Math.imul(a,1103515245)+12345)&0x7fffffff; out.push((a>>>16)&1); } return out; }
function ones(b){ return b.reduce(function(s,x){return s+x;},0); }
