// JAH demo program — Ising energy demo (3 spins)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function ising(s,h,J){ var e=0; for(var i=0;i<s.length;i++)e-=h[i]*s[i];
  for(var i=0;i<J.length;i++)e-=J[i][2]*s[J[i][0]]*s[J[i][1]]; return e; }
var h=[0.5,-0.3,0.2], J=[[0,1,1.0],[1,2,-0.8]];
var best=1e9; for(var m=0;m<8;m++){ var s=[(m&1)?1:-1,(m&2)?1:-1,(m&4)?1:-1]; best=Math.min(best,ising(s,h,J)); }
check("ground energy found", Math.round(best*10)/10, -1.8);
check("annealer seeks the minimum", best<0, true);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
